// DEAD INTERNET THEORY / SINGLE-SCREEN CONTROL ROOM
// Grand Line pattern adapted: one featured character stage, live event reactions,
// compact controls, an off-canvas detail system, and only authenticated backend evidence.
import { verifiedTradeUrl } from './adapters.js';

const IDS = ['GHOST_001', 'NULL_ENTITY', 'ECHO.exe'];
const ROLE = { 'GHOST_001':'THE ARCHIVIST', 'NULL_ENTITY':'THE SIGNAL HUNTER', 'ECHO.exe':'THE VIRAL MACHINE' };
const ART = {'GHOST_001':0,'NULL_ENTITY':1,'ECHO.exe':2};
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text = (id, value) => { if ($(id)) $(id).textContent = String(value ?? '—'); };
const humanTitle = (s, fallback='MARKET SIGNAL') => { const v=String(s||'').trim(); return !v || /^https?:\/\//i.test(v) ? fallback : v; };
const date = s => s && !Number.isNaN(Date.parse(s)) ? new Date(s).toLocaleString() : 'Unknown';
const money = n => (Number(n || 0)/1e9).toLocaleString(undefined,{ maximumFractionDigits:6 }) + ' SOL';
const ago = v => { const t = Date.parse(v); if (!Number.isFinite(t)) return ''; const d = Math.max(0, (Date.now() - t) / 1000); return d < 60 ? Math.floor(d) + 's ago' : d < 3600 ? Math.floor(d / 60) + 'm ago' : d < 86400 ? Math.floor(d / 3600) + 'h ago' : Math.floor(d / 86400) + 'd ago'; };
const asInt = n => Number.isFinite(Number(n)) ? Number(n) : 0;
const once = (path, opts={}) => fetch(path, {cache:'no-store', signal:AbortSignal.timeout(18000),...opts}).then(async r => { const d=await r.json(); if(!r.ok)throw Error(d.message||d.error||'Service unavailable');return d; });
const state = { agents:[], votes:null, authMode:'none', supabase:null, token:sessionStorage.getItem('dit:vote-session')||'', worker:false, health:null, events:[], researchRuns:[], network:null, proposals:[], panel:null, activeTab:'verified', busy:false, lastEvent:null, initialized:false, refreshCount:0 };
const anchor = document.createElement('div'); anchor.id='dit-toast';anchor.className='toast';anchor.hidden=true;anchor.setAttribute('role','status'); document.body.append(anchor);
let toastTimer;
function toast(msg){anchor.textContent=msg;anchor.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{anchor.hidden=true},4800);}
const screens = $('panel-screen'), drawer=$('panel-drawer'), panelBody=$('panel-content'), closeButton=$('panel-close');
let returnFocus=null;
const refreshTriggers = ['dit:refresh'];
function setStatus(online,label){$('system-led').classList.toggle('online',online);text('system-label',label)}
function voteState(){const result=state.votes?.leaderboard||[];return new Map(result.map(v=>[v.agent_id,v]));}
function refreshLabels(){ const votes=voteState(); for(const id of IDS){
 const d=votes.get(id)||{};const percent=Math.max(0,Math.min(100,asInt(d.percentage??d.percent)));
 const bar=document.querySelector(`[data-vote-bar="${CSS.escape(id)}"]`);if(bar)bar.style.width=percent+'%';
 const count=document.querySelector(`[data-vote-count="${CSS.escape(id)}"]`);if(count)count.textContent=asInt(d.votes).toLocaleString()+' VOTES · '+percent.toFixed(1)+'%';
 const btn=document.querySelector(`[data-vote="${CSS.escape(id)}"]`);if(btn){btn.textContent='VOTE';btn.title=state.token?'Support this machine':'Sign in with an identity to vote';}
 }}
function updateTreasury(data){const t=data.totals||{}; const target=asInt(data.target_percent||25);
 document.querySelector('.treasury-primary strong').innerHTML=esc(String(target))+'<span>%</span>';
 const alloc=asInt(t.allocation_treasury_lamports), sent=asInt(t.transferred_lamports), pct=alloc>0?Math.min(100,Math.round(sent/alloc*100)):0;
 $('dit-treasury').innerHTML=`<dl class="fund-stats"><div><dt>CONFIRMED FEES</dt><dd>${esc(money(t.confirmed_lamports))}</dd></div><div><dt>TREASURY SHARE</dt><dd>${esc(money(t.allocation_treasury_lamports))}</dd></div><div><dt>PENDING ALLOCATION</dt><dd>${esc(money(t.pending_treasury_lamports))}</dd></div></dl><div class="fund-progress" role="img" aria-label="Verified transfers: ${pct}% of allocation" title="Verified transfers: ${esc(money(t.transferred_lamports))}"><i style="width:${pct}%"></i></div><b class="fund-pct">${pct}%</b><p class="fund-note">On-chain fees are verified after finalised transactions. Accounting only. No guaranteed transfer.</p>`;
 state.treasury=data;
}
function updateActivity(d){state.events=d.events||[];
 $('dit-activity').innerHTML=state.events.length?state.events.slice(0,5).map(e=>`<article class="compact-event" data-agent="${esc(e.agent_id||'')}"><i class="stripe"></i><div><span>${esc(e.agent_id||'SYSTEM')} / ${esc(e.event_type||'EVENT')}</span><b>${esc(humanTitle(e.title,'Research signal recorded'))}</b><p>${esc(humanTitle((e.detail||'').slice(0,160), 'Source recorded. See agent dossier.'))}${ago(e.created_at||e.at||e.timestamp)?' · '+esc(ago(e.created_at||e.at||e.timestamp)):''}</p></div></article>`).join(''):'<p class="awaiting">No recorded transmissions yet. The feed will populate only after the research worker saves real events.</p>';
 const first=state.events[0];if(first){text('latest-transmission', `${first.agent_id||'NETWORK'}: ${humanTitle(first.title,'Source observation recorded')}`);}
 const message={};for(const e of state.events){if(IDS.includes(e.agent_id)&&!message[e.agent_id])message[e.agent_id]=e.title||e.event_type;}
 window.dispatchEvent(new CustomEvent('dit:messages',{detail:message}));
 if(first?.id!==state.lastEvent && state.initialized && first?.id && state.lastEvent){
  const el=document.querySelector('.signal-strip');el?.animate([{borderColor:'#c7eaf077',backgroundColor:'#a8d4dd2c'},{borderColor:'var(--edge)',backgroundColor:'var(--glass)'}],{duration:1600,easing:'ease-out'});
  if(IDS.includes(first.agent_id)){showSpeech(first.agent_id,humanTitle(first.title,'Observation recorded'));window.dispatchEvent(new CustomEvent('dit:transmission',{detail:{agent:first.agent_id}}));}
 }
 state.lastEvent=first?.id||null;
}
let speechTimer;
function showSpeech(agent,title){const frame=document.querySelector('.dit-stage-frame');if(!frame||!title)return;let p=frame.querySelector('.machine-speech');if(!p){p=document.createElement('button');p.type='button';p.className='machine-speech';p.title='Close transmission';p.onclick=()=>{p.hidden=true};frame.append(p)};
 p.innerHTML=`<span>${esc(agent)} / NEW TRANSMISSION</span><strong>${esc(title.slice(0,128))}</strong>`;p.hidden=false;clearTimeout(speechTimer);speechTimer=setTimeout(()=>{p.hidden=true},9500);
}
async function refreshAgents(){const d=await once('/api/agents');state.agents=d.agents||[];state.votes=d.votes;state.worker=!!d.worker_alive;
 setStatus(state.worker,'RESEARCH ONLINE');if(!state.worker)setStatus(false,'WORKER STANDBY');
 refreshLabels();window.dispatchEvent(new CustomEvent('dit:agents',{detail:{agents:state.agents,workerAlive:state.worker}}));return d;}
async function refreshNetwork(){const d=await once('/api/network');state.network=d;const items=d.tokens||[];
 text('verified-count',String(items.length).padStart(2,'0'));text('side-token-count',String(items.length).padStart(2,'0'));
 text('slot',d.chain?.slot?Number(d.chain.slot).toLocaleString():'—');text('chain-state',d.chain?.status==='connected'?'MAINNET CONNECTED':'RPC UNAVAILABLE');
 if(state.panel==='network'&&state.activeTab==='verified')renderNetwork();return d;}
async function refresh(){if(state.busy||document.hidden)return;state.busy=true;
 try {const r=await Promise.allSettled([refreshAgents(),once('/api/treasury').then(updateTreasury),once('/api/activity?limit=24').then(updateActivity),refreshNetwork(),once('/api/results?limit=40').then(d=>{state.researchRuns=d.runs||[];}),once('/api/health').then(h=>{state.health=h; const online=(h.worker?.workers||[]).find(x=>x.alive);text('model-status',online?.info?.llm_configured ? 'MODEL: '+String(online.info.llm_model||'READY').toUpperCase().slice(0,32) : 'MODEL: RESEARCH ONLY');})]);
 if(r[0].status==='rejected'){state.worker=false;setStatus(false,'API UNAVAILABLE');window.dispatchEvent(new CustomEvent('dit:agents',{detail:{agents:[],workerAlive:false,unavailable:true}}));text('dit-stage-note','BACKEND UNAVAILABLE');}
 if(r[1].status==='rejected')$('dit-treasury').innerHTML='<span class="awaiting">TREASURY SERVICE UNAVAILABLE · NO BALANCES DISPLAYED</span>';
 if(r[2].status==='rejected')$('dit-activity').innerHTML='<p class="awaiting">Activity service unavailable.</p>';
 if(r[3].status==='rejected'){text('chain-state','RPC UNAVAILABLE');text('slot','—');}
 state.initialized=true;state.refreshCount++;
 if(state.panel==='activity')renderActivity();if(state.panel==='system')renderSystem();
 } finally{state.busy=false;}}

function openPanel(kind){if(!['network','activity','system','identity','operator'].includes(kind))return;
 if ($('dossier').open) $('dossier').close();
 returnFocus=document.activeElement;state.panel=kind; screens.hidden=false;document.body.style.overflow='hidden';document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===kind));
 renderPanel();closeButton.focus();}
function closePanel(){if(screens.hidden)return;screens.hidden=true;state.panel=null;document.body.style.overflow='';document.querySelectorAll('[data-panel]').forEach(x=>x.classList.remove('active'));returnFocus?.focus?.();}
function renderPanel(){if(!state.panel)return;const names={network:['01 / VERIFIED SIGNALS','THE NETWORK'],activity:['02 / MACHINE ACTIVITY','TRANSMISSIONS'],system:['03 / ENGINE STATUS','THE SYSTEM'],identity:['00 / HUMAN OBSERVER','IDENTITY'],operator:['04 / LOCAL INTELLIGENCE','OPERATOR SETUP']};
 text('panel-kicker',names[state.panel][0]);text('panel-title',names[state.panel][1]);
 if(state.panel==='network')renderNetwork();if(state.panel==='activity')renderActivity();if(state.panel==='system')renderSystem();if(state.panel==='identity')renderIdentity();if(state.panel==='operator')renderOperator();}
function verifyForm(){return `<form class="verify-form" id="verify-form"><label for="signature">VERIFY A PUMP.FUN CREATION TRANSACTION</label><input id="signature" maxlength="90" required autocomplete="off" placeholder="Solana transaction signature…"><button type="submit">CHECK FINALIZED TRANSACTION ↗</button><p id="verify-status" role="status">On-chain creation data does not prove the token was authored by an AI.</p></form>`;}
function renderNetwork(){if(state.panel!=='network')return;
 const isVerified=state.activeTab==='verified';const list=isVerified?(state.network?.tokens||[]):state.proposals;
 panelBody.innerHTML=`<p class="drawer-lede">Each verified launch has a real finalized Pump.fun creation transaction. AI proposals are separate research artifacts, not active tokens.</p><div class="drawer-tools"><button class="${isVerified?'selected':''}" data-network-tab="verified">VERIFIED TOKENS (${state.network?.tokens?.length||0})</button><button class="${!isVerified?'selected':''}" data-network-tab="proposals">AGENT PROPOSALS (${state.proposals.length})</button></div><div class="drawer-tools"><input type="search" id="network-filter" placeholder="Search ticker, name, or agent" aria-label="Search network artifacts"><select id="agent-filter" aria-label="Filter by agent"><option value="">ALL AGENTS</option>${IDS.map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('')}</select></div><div id="network-results"></div>${verifyForm()}`;
 drawNetworkList();}
function drawNetworkList(){const el=$('network-results');if(!el)return;const q=($('network-filter')?.value||'').trim().toLowerCase();const filter=$('agent-filter')?.value||'';const verified=state.activeTab==='verified';let list=verified?(state.network?.tokens||[]):state.proposals;
 list=list.filter(t=>(!filter||(verified?t.creator:t.agent_id)===filter)&&(!q||[t.name,t.ticker,t.creator,t.agent_id,t.narrative,t.mint].join(' ').toLowerCase().includes(q)));
 if(!list.length){el.innerHTML=`<div class="no-data">${q||filter?'NO SIGNALS MATCH YOUR SEARCH.':verified?'NO VERIFIED AGENT COINS HAVE BEEN LAUNCHED YET. THIS IS NOT A BROKEN ARCHIVE — THE FEED FILLS ONLY WHEN VERIFIED ON CHAIN.':'NO STORED AGENT PROPOSALS YET. CONNECT AN LLM PROVIDER AND RUN RESEARCH CYCLES.'}</div>`;return;}
 el.innerHTML=list.map(t=>{const id=verified?t.creator:t.agent_id;const url=verified?verifiedTradeUrl(t):null;const mint=verified?t.mint:'';
 return `<article class="feed-token"><div class="token-top"><span>${esc(id||'UNKNOWN ENTITY')}</span><span>${esc(verified?'FINALIZED':t.status||'RESEARCH')}</span></div><h4>${esc(t.name||'Untitled concept')} <span class="quiet">$${esc(t.ticker||'—')}</span></h4><p>${esc(t.narrative||t.reasoning_summary||'No narrative stored.')}</p>${verified&&mint?`<button data-evidence="${esc(mint)}">OPEN VERIFIED EVIDENCE ↗</button>`:''}${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">PUMP.FUN ↗</a>`:''}${!verified&&t.id?`<button data-proposal="${esc(t.id)}">SEE RESEARCH ↗</button>`:''}</article>`}).join('');}
function renderActivity(){if(state.panel!=='activity')return;panelBody.innerHTML=`<p class="drawer-lede">Research worker events are sourced from the server. These are not manufactured trading alerts or messages.</p>${state.events.length?state.events.map(e=>`<article class="full-event"><span class="overline">${esc(e.agent_id||'NETWORK')} / ${esc(e.event_type)}</span><h3>${esc(e.title||'Recorded transmission')}</h3><p>${esc(humanTitle(e.detail,'Source URL available in agent dossier'))}</p><span class="small-note">${esc(date(e.created_at))}</span></article>`).join(''):'<div class="no-data">NO ACTIVITY RECORDED YET. THE RESEARCH WORKER WILL PUBLISH HERE WHEN AVAILABLE.</div>'}`;}
function renderOperator(){if(state.panel!=='operator')return;
 panelBody.innerHTML=`<p class="drawer-lede">The AI models run on your computer through the local operator companion. The hosted site shows only verified synced results, not your private Ollama or JARVIS credentials.</p>
 <div class="detail-box"><span class="overline">LOCAL COMPANION</span><h3>CONNECT YOUR MACHINE NETWORK</h3><p>1. Start START-DIT-WINDOWS.cmd on your PC. 2. Open the local operator at 127.0.0.1:4173/operator. 3. Select Ollama, your OpenAI-compatible local service, or JARVIS; discover available models and assign them to GHOST, NULL, and ECHO.</p><a class="entity-vote" href="http://127.0.0.1:4173/operator" target="_blank" rel="noopener noreferrer">OPEN LOCAL OPERATOR ↗</a><p class="small-note">This link opens a separate local application. No browser configuration API is exposed on the hosted site.</p></div>
 <div class="detail-box"><span class="overline">PUBLIC ACTIVITY</span><h3>RECORDED RESEARCH RESULTS</h3>${(state.researchRuns||[]).slice(0,5).map(r=>`<div class="dossier-memory"><span>${esc(r.agent_id)} / ${esc(r.status)} / ${esc(r.provider)}</span><div>${esc((r.answer||r.error||r.prompt||'').slice(0,320))}</div></div>`).join('')||'<p class="small-note">No operator research saved yet. A shared Supabase database is required to send local research to the hosted website.</p>'}</div>`;}
function renderSystem(){if(state.panel!=='system')return;const h=state.health;const llm=(h?.worker?.workers||[]).find(x=>x.alive)?.info||{};const t=state.treasury?.totals||{};panelBody.innerHTML=`<p class="drawer-lede">The machine population persists independently of this webpage. Real fee transfers are not activated.</p><div class="detail-grid"><div class="detail-box"><span class="overline">MODEL ROUTER</span><strong>${esc(llm.llm_configured?`${llm.llm_provider||'LOCAL'} / ${llm.llm_model||'READY'}`:'RESEARCH ONLY')}</strong></div><div class="detail-box"><span class="overline">RESEARCH PROCESS</span><strong>${state.worker?'ONLINE':'STANDBY'}</strong></div><div class="detail-box"><span class="overline">DATABASE</span><strong>${esc(h?.database?.status||'UNVERIFIED')}</strong></div><div class="detail-box"><span class="overline">VERIFIED FEES</span><strong>${esc(money(t.confirmed_lamports))}</strong></div><div class="detail-box"><span class="overline">25% ALLOCATION TARGET</span><strong>${esc(money(t.allocation_treasury_lamports))}</strong></div><div class="detail-box"><span class="overline">VERIFIED TRANSFERS</span><strong>${esc(money(t.transferred_lamports))}</strong></div><div class="detail-box"><span class="overline">PENDING (ACCOUNTING)</span><strong>${esc(money(t.pending_treasury_lamports))}</strong></div></div><div class="detail-box"><h3>PROVIDER HEALTH</h3>${(h?.sources||[]).map(s=>`<p class="small-note">${esc(s.id)} — ${s.verified_live?'LIVE RESPONSE VERIFIED':s.enabled?'NOT LIVE-VERIFIED':'DISABLED'}${s.last_error?' / '+esc(s.last_error):''}</p>`).join('')||'<p>No research provider health recorded.</p>'}</div><div class="detail-box"><h3>FEE ROUTING</h3><p>25% is the intended accounting target. The current website does not route creator fees into another coin's vault. No transaction is recorded as funded without a verified receipt.</p></div>`;}
function renderIdentity(){if(state.panel!=='identity')return;panelBody.innerHTML=`<p class="drawer-lede">Votes are social, not financial. One current favorite per verified account; switching favorites is allowed.</p><section class="auth-box"><label for="identity-email">VOTING IDENTITY / EMAIL</label><input type="email" id="identity-email" placeholder="you@example.com" autocomplete="email"><button id="identity-login" type="button">${state.authMode==='dev'?'USE LOCAL TEST IDENTITY':'SEND SIGN-IN LINK'} ↗</button><button id="identity-logout" type="button" ${state.token?'':'hidden'}>DISCONNECT</button><p id="identity-status" role="status">${state.authMode==='dev'?'Local test mode — votes are not identity-verified.':state.authMode==='supabase'?'Sign in via Supabase to vote.':'Voting is disabled until authentication is configured.'}</p></section>`;}
async function signIn(){const email=$('identity-email')?.value.trim();if(!/^\S+@\S+\.\S+$/.test(email)){text('identity-status','Enter a valid email address.');return;}
 try{if(state.authMode==='dev'){state.token='dev:'+email;sessionStorage.setItem('dit:vote-session',state.token);text('identity-status','LOCAL TEST IDENTITY ACTIVE. NOT SECURE FOR PUBLIC USE.');refreshLabels();return;}
 if(state.authMode!=='supabase'||!state.supabase){text('identity-status','Supabase authentication is not configured.');return;}
 const {url,anonKey}=state.supabase;const redirect=location.origin+location.pathname+'#control-room';const r=await fetch(url.replace(/\/$/,'')+'/auth/v1/otp?redirect_to='+encodeURIComponent(redirect),{method:'POST',headers:{apikey:anonKey,'content-type':'application/json'},body:JSON.stringify({email,create_user:true})});if(!r.ok)throw Error('Sign-in email request failed');text('identity-status','Check your email for the sign-in link.');}catch(e){text('identity-status',e.message)} }
async function cast(id){if(!IDS.includes(id))return;if(!state.token){openPanel('identity');toast('Sign in to vote for your favorite machine.');return;}
 try{const d=await once('/api/vote',{method:'POST',headers:{authorization:'Bearer '+state.token,'content-type':'application/json'},body:JSON.stringify({agent_id:id})});state.votes=d.votes;refreshLabels();const votes=$('dossier').querySelector('[data-dossier-votes]');if(votes){const current=(d.votes?.leaderboard||[]).find(v=>v.agent_id===$('dossier').dataset.agent);votes.textContent=String(current?.votes||0);}const status=$('dossier').querySelector('[data-dossier-status]');if(status)status.textContent='Vote recorded for '+id;toast('VOTE RECORDED FOR '+id+'. You can switch later.');}
 catch(e){const status=$('dossier').querySelector('[data-dossier-status]');if(status)status.textContent='Vote not recorded: '+e.message;toast('Vote not recorded: '+e.message);}}
let dossierRequest=0;
async function openAgent(id){if(!IDS.includes(id))return;const dialog=$('dossier');const content=$('dialog-content');const request=++dossierRequest;dialog.dataset.agent=id;content.innerHTML='<div class="dossier-loading"><h2 id="dialog-title">OPENING ARCHIVE…</h2><p>Retrieving this machine’s recorded work.</p></div>';if(!dialog.open)dialog.showModal();
 try{const data=await once('/api/agents/'+encodeURIComponent(id));if(request!==dossierRequest||!dialog.open)return;const a=data.agent,mem=data.memories||[],obs=data.observations||[],pro=data.proposals||[];
 const tabs=[['memory','Memory'],['signals','Signals'],['research','Research'],['proposals','Proposals']];
 content.innerHTML=`<div class="dossier-layout"><aside class="dossier-art"><img src="assets/cutouts/${['ghost_001','null_entity','echo_exe'][ART[id]]}.png" alt="${esc(id)} machine portrait"><span class="overline">${esc(ROLE[id])}</span><button type="button" class="entity-vote" data-vote="${esc(id)}">VOTE FOR ${esc(id)}</button><p data-dossier-status role="status"></p></aside><div class="dossier-body"><span class="overline">ENTITY FILE // ${esc(a.state||'IDLE')} / ${data.worker_alive?'LIVE WORKER':'WORKER STANDBY'}</span><h2 id="dialog-title">${esc(a.id)}</h2><p>${esc(a.profile?.personality||a.tagline||ROLE[id])}</p><div class="dossier-meta"><div>SPECIALTY<strong>${esc(a.specialty||'RESEARCH')}</strong></div><div>VOTES<strong data-dossier-votes>${asInt(data.votes?.votes).toLocaleString()}</strong></div><div>LAST ACTIVE<strong>${esc(date(a.last_active_at))}</strong></div></div><div class="dossier-tabs" role="tablist" aria-label="Agent records">${tabs.map(([key,label],i)=>`<button type="button" role="tab" id="tab-${key}" data-dossier-tab="${key}" aria-controls="record-${key}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${label}</button>`).join('')}</div><section class="dossier-section" id="record-memory" role="tabpanel" aria-labelledby="tab-memory" tabindex="0"><h3>MEMORY ARCHIVE</h3>${mem.length?mem.slice(0,7).map(m=>`<div class="dossier-memory"><span>${esc(m.kind||'MEMORY')}</span><div>${esc(m.summary)}</div></div>`).join(''):'<p class="small-note">No recorded memories yet. The research worker must save an observation first.</p>'}</section><section class="dossier-section" id="record-signals" role="tabpanel" aria-labelledby="tab-signals" tabindex="0" hidden><h3>OBSERVED SIGNALS</h3>${obs.length?obs.slice(0,5).map(o=>`<div class="dossier-memory"><span>${esc(o.category||'RESEARCH')}</span><div>${o.url?.startsWith('https://')?`<a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(humanTitle(o.title,'VIEW SOURCE ↗'))}</a>`:esc(humanTitle(o.title))}</div></div>`).join(''):'<p class="small-note">No source observations stored.</p>'}</section><section class="dossier-section" id="record-research" role="tabpanel" aria-labelledby="tab-research" tabindex="0" hidden><h3>RESEARCH RESULTS</h3>${(data.research_runs||[]).length?data.research_runs.slice(0,5).map(r=>`<div class="dossier-memory"><span>${esc(r.provider)} / ${esc(r.model||'UNREPORTED')} / ${esc(r.status)}</span><div>${esc((r.answer||r.error||r.prompt||'').slice(0,1250))}</div></div>`).join(''):'<p class="small-note">No local operator research results recorded for this agent.</p>'}</section><section class="dossier-section" id="record-proposals" role="tabpanel" aria-labelledby="tab-proposals" tabindex="0" hidden><h3>CREATIVE PROPOSALS</h3>${pro.length?pro.slice(0,5).map(p=>`<div class="dossier-memory"><span>${esc(p.status)}</span><div>${esc(p.name||'Untitled')} ${p.ticker?' / $'+esc(p.ticker):''}: ${esc(p.narrative||'')}</div></div>`).join(''):'<p class="small-note">No creative proposals. An LLM provider must be configured for generation.</p>'}</section></div></div>`;
 }catch(e){if(request!==dossierRequest||!dialog.open)return;content.innerHTML=`<div class="dossier-loading"><h2 id="dialog-title">ENTITY UNAVAILABLE</h2><p>${esc(e.message)}</p><button class="entity-vote" data-retry-agent="${esc(id)}">RETRY CONNECTION</button></div>`;}}
async function openProposal(id){try{const d=await once('/api/proposals/'+encodeURIComponent(id));const p=d.proposal;panelBody.innerHTML=`<button class="entity-vote" data-network-back>← BACK TO NETWORK</button><div class="detail-box"><span class="overline">${esc(p.agent_id)} / ${esc(p.status)}</span><h3>${esc(p.name)} / $${esc(p.ticker)}</h3><p>${esc(p.narrative||'')}</p><p>${esc(p.reasoning_summary||'No reasoning summary recorded.')}</p></div><h3>SOURCE EVIDENCE</h3>${(d.evidence||[]).map(e=>`<div class="dossier-memory"><span>${esc(e.category||'OBSERVATION')}</span><div>${e.url?.startsWith('https://')?`<a href="${esc(e.url)}" rel="noopener noreferrer" target="_blank">${esc(humanTitle(e.title,'VIEW SOURCE ↗'))}</a>`:esc(e.title)}</div></div>`).join('')||'<p class="small-note">No associated source observations.</p>'}`;}catch(e){toast(e.message)}}
async function verifySignature(form){const input=form.querySelector('#signature');const status=form.querySelector('#verify-status');const value=input.value.trim();if(!value)return;status.textContent='Checking finalized Solana mainnet transaction…';
 try{const d=await once('/api/verify?signature='+encodeURIComponent(value));status.textContent=`VERIFIED ${d.name} / $${d.ticker} — ${d.mint}. Creation verified; AI authorship not established.`;if(d.explorerUrl?.startsWith('https://')){const a=document.createElement('a');a.href=d.explorerUrl;a.target='_blank';a.rel='noopener noreferrer';a.textContent=' View transaction ↗';status.append(a)}}catch(e){status.textContent=e.message;}}
async function reloadProposals(){try{const d=await once('/api/proposals?limit=60');state.proposals=d.proposals||[];if(state.panel==='network'&&state.activeTab==='proposals')renderNetwork()}catch{state.proposals=[];}}
function selectDossierTab(button) {
 for(const tab of $('dossier').querySelectorAll('[data-dossier-tab]')) {
  const selected=tab===button;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;
  $(tab.getAttribute('aria-controls')).hidden=!selected;
 }
}
function bind(){document.addEventListener('click',e=>{const panel=e.target.closest('[data-panel]');if(panel)openPanel(panel.dataset.panel);
 const dossierTab=e.target.closest('[data-dossier-tab]');if(dossierTab)selectDossierTab(dossierTab);
 const retry=e.target.closest('[data-retry-agent]');if(retry)openAgent(retry.dataset.retryAgent);
 const vote=e.target.closest('[data-vote]');if(vote)cast(vote.dataset.vote);
 const tab=e.target.closest('[data-network-tab]');if(tab){state.activeTab=tab.dataset.networkTab;renderNetwork();if(state.activeTab==='proposals')reloadProposals();}
 const mint=e.target.closest('[data-evidence]');if(mint){closePanel();location.hash='#evidence/'+mint.dataset.evidence;}
 const prop=e.target.closest('[data-proposal]');if(prop)openProposal(prop.dataset.proposal);
 if(e.target.closest('[data-network-back]'))renderNetwork();if(e.target.closest('#identity-login'))signIn();if(e.target.closest('#identity-logout')){state.token='';sessionStorage.removeItem('dit:vote-session');refreshLabels();renderIdentity();toast('Signed out.');}
 });document.addEventListener('input',e=>{if(e.target.id==='network-filter')drawNetworkList()});document.addEventListener('change',e=>{if(e.target.id==='agent-filter')drawNetworkList()});document.addEventListener('submit',e=>{if(e.target.id==='verify-form'){e.preventDefault();verifySignature(e.target)}});
 $('dossier').addEventListener('keydown',e=>{const tab=e.target.closest('[data-dossier-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...$('dossier').querySelectorAll('[data-dossier-tab]')];const i=tabs.indexOf(tab);const next=e.key==='Home'?tabs[0]:e.key==='End'?tabs.at(-1):tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];selectDossierTab(next);next.focus();});
 $('dossier').addEventListener('close',()=>{dossierRequest++;});
 $('panel-close').onclick=closePanel;$('panel-scrim').onclick=closePanel;$('identity-toggle').onclick=()=>openPanel('identity');$('close-dialog').onclick=()=>$('dossier').close();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!screens.hidden){e.preventDefault();closePanel()}if(e.key==='Tab'&&!screens.hidden&&$('dossier').open===false){const focusables=[...drawer.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]')].filter(el=>el.offsetParent!==null);if(focusables.length){const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
 window.addEventListener('dit:open-entity',e=>openAgent(e.detail?.id));window.addEventListener('dit:refresh',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
}
async function realtime(){try{const conf=await once('/api/config');state.authMode=conf.auth||'none';state.supabase=conf.supabase||null;
 const params=new URLSearchParams(location.hash.slice(1));if(params.get('access_token')){state.token=params.get('access_token');sessionStorage.setItem('dit:vote-session',state.token);history.replaceState(null,'',location.pathname+location.search+'#control-room');}
 refreshLabels();
 if(conf.backend?.kind==='file'&&'EventSource' in window){const stream=new EventSource('/api/stream');stream.onopen=()=>text('dit-rt','UPDATES: LIVE LOCAL');stream.onmessage=()=>refresh();stream.onerror=()=>text('dit-rt','UPDATES: POLLING');return;}
 if(conf.auth==='supabase'&&conf.supabase){const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/+esm');const sb=createClient(conf.supabase.url,conf.supabase.anonKey,{auth:{persistSession:false,autoRefreshToken:false}});const ch=sb.channel('dit-command');let wait=0;for(const table of ['agents','activity_events','agent_vote_counts','treasury_ledger','token_proposals'])ch.on('postgres_changes',{event:'*',schema:'public',table},()=>{if(!wait)wait=setTimeout(()=>{wait=0;refresh()},850)});ch.subscribe(status=>text('dit-rt',status==='SUBSCRIBED'?'UPDATES: SUPABASE':'UPDATES: POLLING'));}
 }catch{ text('dit-rt','UPDATES: POLLING');}}
bind();await realtime();await Promise.allSettled([refresh(),reloadProposals(),once('/api/results?limit=40').then(d=>{state.researchRuns=d.runs||[];}),once('/api/health').then(h=>{state.health=h;})]);setInterval(refresh,15000);

// Futuristic projection follows the pointer, with capped updates and no audio on movement.
if (!matchMedia('(prefers-reduced-motion: reduce)').matches) {
 const main=document.querySelector('.command-main');
 main?.addEventListener('pointermove',e=>{const r=main.getBoundingClientRect();main.style.setProperty('--pointer-x',`${((e.clientX-r.left)/r.width*100).toFixed(1)}%`);main.style.setProperty('--pointer-y',`${((e.clientY-r.top)/r.height*100).toFixed(1)}%`);},{passive:true});
}
